CREATE TABLE `estimate_snapshots` (
	`id` text PRIMARY KEY NOT NULL,
	`lead_id` text NOT NULL,
	`submission_id` text NOT NULL,
	`version` integer NOT NULL,
	`engine_revision` integer NOT NULL,
	`questions_json` text NOT NULL,
	`answers_json` text NOT NULL,
	`defaulted_json` text NOT NULL,
	`line_items_json` text NOT NULL,
	`flags_json` text NOT NULL,
	`low` integer NOT NULL,
	`mid` integer NOT NULL,
	`high` integer NOT NULL,
	`below_minimum` integer NOT NULL,
	`sqft` real NOT NULL,
	`railing_lf` integer NOT NULL,
	`service_area` text NOT NULL,
	`created_at` integer DEFAULT (cast(unixepoch('subsec') * 1000 as integer)) NOT NULL,
	FOREIGN KEY (`lead_id`) REFERENCES `leads`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`submission_id`) REFERENCES `form_submissions`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`version`) REFERENCES `estimator_versions`(`version`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
CREATE UNIQUE INDEX `estimate_snapshots_submission` ON `estimate_snapshots` (`submission_id`);--> statement-breakpoint
CREATE INDEX `estimate_snapshots_lead` ON `estimate_snapshots` (`lead_id`,`created_at`);--> statement-breakpoint
CREATE TABLE `estimator_draft` (
	`id` integer PRIMARY KEY DEFAULT 1 NOT NULL,
	`document_json` text NOT NULL,
	`revision` integer DEFAULT 1 NOT NULL,
	`updated_at` integer DEFAULT (cast(unixepoch('subsec') * 1000 as integer)) NOT NULL,
	`updated_by` text,
	FOREIGN KEY (`updated_by`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "estimator_draft_single_row" CHECK("estimator_draft"."id" = 1)
);
--> statement-breakpoint
CREATE TABLE `estimator_versions` (
	`version` integer PRIMARY KEY NOT NULL,
	`document_json` text NOT NULL,
	`draft_revision` integer,
	`published_at` integer NOT NULL,
	`published_by` text,
	FOREIGN KEY (`published_by`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE set null
);
