 deck structure"},{"enabled":true,"price":{"price":6000},"value":"largeRestricted","label":"Large, tall, or hard-to-reach deck"},{"enabled":true,"price":{"price":0},"value":"homeowner","label":"I''ll remove it myself"},{"enabled":true,"price":{"price":3250},"value":"unsure","label":"Not sure"}]},{"key":"framingSound","label":"Does the existing framing appear sound?","default":null,"options":[{"enabled":true,"price":{},"value":"yes","label":"Yes"},{"enabled":true,"price":{},"value":"no","label":"No","reviewFlag":"Existing framing condition unknown"},{"enabled":true,"price":{},"value":"unsure","label":"Not sure","reviewFlag":"Existing framing condition unknown"}]},{"key":"rot","label":"Any visible rot?","default":null,"options":[{"enabled":true,"price":{},"value":"yes","label":"Yes","reviewFlag":"Visible rot in existing framing"},{"enabled":true,"price":{},"value":"no","label":"No"},{"enabled":true,"price":{},"value":"unsure","label":"Not sure"}]},{"key":"unstable","label":"Does the deck move, shake, or feel unstable?","default":null,"options":[{"enabled":true,"price":{},"value":"yes","label":"Yes","reviewFlag":"Existing deck moves or feels unstable"},{"enabled":true,"price":{},"value":"no","label":"No"},{"enabled":true,"price":{},"value":"unsure","label":"Not sure"}]},{"key":"fascia","label":"Fascia (the trim board around the deck''s edge)","default":null,"options":[{"enabled":true,"price":{"perLf":22.5},"value":"standard","label":"Standard fascia"},{"enabled":true,"price":{"perLf":35},"value":"premium","label":"Matching or white composite fascia"}]},{"key":"pattern","label":"Board layout","help":"Composite decks include one picture-frame border.","default":null,"options":[{"enabled":true,"price":{"pct":0},"value":"standard","label":"Standard (one picture-frame border)"},{"enabled":true,"price":{"pct":0.02},"value":"contrasting","label":"Contrasting-color border"},{"enabled":true,"price":{"pct":0.04},"value":"double","label":"Double picture frame"},{"enabled":true,"p